using System; using System.Diagnostics; using System.IO; using System.Windows; using System.Windows.Controls; using System.Windows.Interop; using System.Windows.Media; using System.Windows.Media.Imaging; using System.Windows.Threading; namespace EtoDesktop { internal sealed class DesktopLayer { Window wall,bar; TextBlock clock; DispatcherTimer timer; public void Apply(string path,string type,bool barOn,bool clockOn){if(!string.IsNullOrEmpty(path)&&File.Exists(path))MakeWallpaper(path,type); SetTaskbar(barOn); SetClock(clockOn);} void MakeWallpaper(string path,string type){wall?.Close(); wall=new Window{WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,Width=SystemParameters.PrimaryScreenWidth,Height=SystemParameters.PrimaryScreenHeight,Left=0,Top=0,Background=Brushes.Black}; var g=new Grid(); if(type=="video"){var v=new MediaElement{Source=new Uri(path),LoadedBehavior=MediaState.Manual,UnloadedBehavior=MediaState.Stop,Stretch=Stretch.UniformToFill,Volume=0};v.Loaded+=(s,e)=>v.Play();g.Children.Add(v);} else if(type=="gif"){var i=new Image{Stretch=Stretch.UniformToFill};var d=new GifBitmapDecoder(new Uri(path),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);i.Source=d.Frames[0];g.Children.Add(i);if(d.Frames.Count>1){int n=0;var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};t.Tick+=(s,e)=>{n=(n+1)%d.Frames.Count;i.Source=d.Frames[n];};t.Start();}} else g.Children.Add(new Image{Source=new BitmapImage(new Uri(path)),Stretch=Stretch.UniformToFill}); wall.Content=g; wall.Loaded+=(s,e)=>{var h=new WindowInteropHelper(wall).Handle;NativeMethods.SetParent(h,NativeMethods.Worker());};wall.Show();} void SetTaskbar(bool on){var native=NativeMethods.FindWindow("Shell_TrayWnd",null);if(native!=IntPtr.Zero)NativeMethods.ShowWindow(native,on?NativeMethods.SW_HIDE:NativeMethods.SW_SHOW);if(!on){bar?.Hide();return;} if(bar==null){bar=new Window{WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,ShowInTaskbar=false,Topmost=true,Height=46,Background=new SolidColorBrush(Color.FromArgb(235,20,24,32))};var p=new DockPanel{Margin=new Thickness(10,0,10,0)};p.Children.Add(new Button{Content="ETO",Width=60,Margin=new Thickness(0,7,8,7)});clock=new TextBlock{Foreground=Brushes.White,FontSize=16,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Right};DockPanel.SetDock(clock,Dock.Right);p.Children.Add(clock);bar.Content=p;}bar.Width=SystemParameters.PrimaryScreenWidth;bar.Left=0;bar.Top=SystemParameters.PrimaryScreenHeight-bar.Height;bar.Show();} void SetClock(bool on){if(timer==null){timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=(s,e)=>Update();}if(on){timer.Start();Update();}else timer.Stop();}void Update(){if(clock!=null)clock.Text=DateTime.Now.ToString("HH:mm:ss  |  dd/MM/yyyy");} public void Restore(){timer?.Stop();bar?.Hide();wall?.Close();var n=NativeMethods.FindWindow("Shell_TrayWnd",null);if(n!=IntPtr.Zero)NativeMethods.ShowWindow(n,NativeMethods.SW_SHOW);}}}